<?php require 'header.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $email=trim($_POST['email']??'');$pass=$_POST['password']??'';$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if($u&&password_verify($pass,$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];$pdo->prepare('INSERT INTO activity_logs(user_id,action,details) VALUES(?,?,?)')->execute([$u['id'],'เข้าสู่ระบบ','']);header('Location: index.php');exit;}flash('อีเมลหรือรหัสผ่านไม่ถูกต้อง');} ?>
